// ===== i18n Engine =====
const i18n = {
  currentLang: localStorage.getItem('mkLang') || 'en',

  t(key) {
    let result;
    if (translations[this.currentLang] && translations[this.currentLang][key] !== undefined) {
      result = translations[this.currentLang][key];
    } else if (translations['en'] && translations['en'][key] !== undefined) {
      result = translations['en'][key];
    } else {
      result = key;
    }
    return result;
  },

  setLang(lang) {
    if (!translations[lang]) return;
    this.currentLang = lang;
    localStorage.setItem('mkLang', lang);
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : lang === 'ja' ? 'ja' : 'en';
    this.applyTranslations();
    this.updateLangButtons();
    this.updateFooterLang();
  },

  updateFooterLang() {
    // 更新Footer语言版本显示
    document.querySelectorAll('.footer-premium-lang-section').forEach(section => {
      const sectionLang = section.getAttribute('data-lang');
      if (sectionLang === this.currentLang) {
        section.style.display = 'block';
      } else {
        section.style.display = 'none';
      }
    });
    // 更新免责声明语言版本（标题和内容）
    const disclaimerContainer = document.querySelector('.footer-premium-bottom-unified');
    if (disclaimerContainer) {
      disclaimerContainer.querySelectorAll('.footer-premium-disclaimer-title, .footer-premium-disclaimer-text').forEach(element => {
        const disclaimerLang = element.getAttribute('data-lang-disclaimer');
        if (disclaimerLang) {
          element.style.display = disclaimerLang === this.currentLang ? 'block' : 'none';
        } else {
          element.style.display = this.currentLang === 'zh' ? 'block' : 'none';
        }
      });
    }
    // 更新企业精神语言版本
    document.querySelectorAll('.spirit-lang-section').forEach(section => {
      const sectionLang = section.getAttribute('data-lang');
      section.style.display = sectionLang === this.currentLang ? 'block' : 'none';
    });
    // 更新服务段落语言版本
    document.querySelectorAll('.services-para-lang').forEach(section => {
      const sectionLang = section.getAttribute('data-lang');
      section.style.display = sectionLang === this.currentLang ? 'block' : 'none';
    });
  },

  applyTranslations() {
    // Text content
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      const val = this.t(key);
      if (val !== undefined) el.innerHTML = val;
    });
    // Placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      const val = this.t(key);
      if (val) el.placeholder = val;
    });
    // Page title
    const titleEl = document.querySelector('title');
    if (titleEl) {
      const base = 'Mygo Kasumi LLC';
      const page = titleEl.getAttribute('data-i18n-title');
      if (page) titleEl.textContent = this.t(page) + ' – ' + base;
    }
  },

  updateLangButtons() {
    document.querySelectorAll('.lang-btn').forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-lang') === this.currentLang);
    });
  },

  init() {
    document.documentElement.lang = this.currentLang === 'zh' ? 'zh-CN' : this.currentLang === 'ja' ? 'ja' : 'en';
    this.applyTranslations();
    this.updateLangButtons();
    this.updateFooterLang();
    document.querySelectorAll('.lang-btn').forEach(btn => {
      btn.addEventListener('click', () => this.setLang(btn.getAttribute('data-lang')));
    });
  }
};

document.addEventListener('DOMContentLoaded', () => i18n.init());